    | MACRO_IS { $$ = $1; } | MACRO_EXPR { $$ = $1; } | MACRO_IDENT { $$ = $1; }
    | MACRO_BLOCK { $$ = $1; } | MACRO_STMT { $$ = $1; } ;

macro_category := MACRO_EXPR { $$ = $1; } | MACRO_IDENT { $$ = $1; }
    | TYPE_KW { $$ = $1; } | MACRO_BLOCK { $$ = $1; } | MACRO_STMT { $$ = $1; } ;

